 synchronized void receive(Intent i){if(i==null)return;String action=i.getAction();if(!Intent.ACTION_SEND.equals(action)&&!Intent.ACTION_SEND_MULTIPLE.equals(action))return;CharSequence t=i.getCharSequenceExtra(Intent.EXTRA_TEXT);if(t!=null)shareText=t.toString();if(Intent.ACTION_SEND.equals(action)){Uri u=i.getParcelableExtra(Intent.EXTRA_STREAM);if(u!=null&&"content".equals(u.getScheme()))shares.add(u);}else{ArrayList<Uri> list=i.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(list!=null)for(Uri u:list)if("content".equals(u.getScheme()))shares.add(u);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==10&&chooser!=null){Uri[] r=null;if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){r=new Uri[data.getClipData().getItemCount()];for(int i=0;i<r.length;i++)r[i]=data.getClipData().getItemAt(i).getUri();}else if(data.getData()!=null)r=new Uri[]{data.getData()};}chooser.onReceiveValue(r);chooser=null;}}
