 final class Bridge {
 @JavascriptInterface public String call(String action,String raw){try{JSONObject a=new JSONObject(raw);Object v=JSONObject.NULL;switch(action){case "status":v=collector.status();break;case "activity":collector.collect();v=new JSONObject().put("rows",collector.rows(a.getLong("from"),a.getLong("to"))).put("status",collector.status());break;case "configure":collector.configure(a);CollectJob.schedule(MainActivity.this);CollectJob.EXEC.execute(()->CollectJob.run(MainActivity.this));break;case "eraseActivity":collector.erase();break;case "disableCloud":collector.disableCloud();break;case "permission":runOnUiThread(()->startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS)));break;case "locationPermission":runOnUiThread(()->{if(!collector.locationAllowed())requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},20);else if(checkSelfPermission(Manifest.permission.ACCESS_BACKGROUND_LOCATION)!=PackageManager.PERMISSION_GRANTED){startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}});break;case "openUrl":Uri u=Uri.parse(a.getString("url"));if(!"https".equals(u.getScheme())||!"www.openstreetmap.org".equals(u.getHost()))throw new Exception("URL не разрешён");runOnUiThread(()->startActivity(new Intent(Intent.ACTION_VIEW,u)));break;case "copy":runOnUiThread(()->getSystemService(android.content.ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("LinkUp",a.optString("text"))));break;case "paste":{android.content.ClipboardManager cm=getSystemService(android.content.ClipboardManager.class);ClipData clip=cm.getPrimaryClip();v=clip==null?"":clip.getItemAt(0).coerceToText(MainActivity.this).toString();break;}case "downloadBegin":{String name=a.getString("name").replaceAll("[/\\\\\\x00]","_");ContentValues cv=new ContentValues();cv.put(MediaStore.Downloads.DISPLAY_NAME,name);cv.put(MediaStore.Downloads.MIME_TYPE,a.optString("mime","application/octet-stream"));cv.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/LinkUp");cv.put(MediaStore.Downloads.IS_PENDING,1);Uri uri=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,cv);if(uri==null)throw new Exception("Не удалось создать файл");String id=UUID.randomUUID().toString();downloads.put(id,uri);v=id;break;}case "downloadChunk":{Uri uri=downloads.get(a.getString("id"));if(uri==null)throw new Exception("Файл не открыт");try(OutputStream out=getContentResolver().openOutputStream(uri,"wa")){out.write(android.util.Base64.decode(a.getString("data"),android.util.Base64.DEFAULT));}break;}case "downloadEnd":case "downloadAbort":{Uri uri=downloads.remove(a.getString("id"));if(uri!=null){if(action.equals("downloadAbort"))getContentResolver().delete(uri,null,null);else{ContentValues cv=new ContentValues();cv.put(MediaStore.Downloads.IS_PENDING,0);getContentResolver().update(uri,cv,null,null);}}break;}case "shareList":{JSONArray list=new JSONArray();synchronized(MainActivity.this){for(int i=0;i<shares.size();i++){Uri uri=shares.get(i);String name="file";long size=-1;try(Cursor q=getContentResolver().query(uri,null,null,null,null)){if(q!=null&&q.moveToFirst()){int n=q.getColumnIndex(OpenableColumns.DISPLAY_NAME),z=q.getColumnIndex(OpenableColumns.SIZE);if(n>=0)name=q.getString(n);if(z>=0)size=q.getLong(z);}}list.put(new JSONObject().put("index",i).put("name",name).put("size",size).put("mime",getContentResolver().getType(uri)));}v=new JSONObject().put("text",shareText).put("files",list);}break;}case "shareRead":{int index=a.getInt("index");Uri uri; synchronized(MainActivity.this){uri=shares.get(index);}long off=a.getLong("offset");try(InputStream in=getContentResolver().openInputStream(uri)){long skipped=0;while(skipped<off){long n=in.skip(off-skipped);if(n<=0){if(in.read()==-1)break;n=1;}skipped+=n;}byte[] buf=new byte[192*1024];int n=0,x;while(n<buf.length&&(x=in.read(buf,n,buf.length-n))>0)n+=x;v=android.util.Base64.encodeToString(buf,0,n,android.util.Base64.NO_WRAP);}break;}case "shareClear":synchronized(MainActivity.this){shareText="";shares.clear();}break;default:throw new Exception("Неизвестная операция");}return new JSONObject().put("value",v).toString();}catch(Exception e){try{return new JSONObject().put("error",String.valueOf(e.getMessage())).toString();}catch(Exception ignored){return "{\"error\":\"Unknown\"}";}}}
 }
